package com.acme.billing;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InvoiceService {

    private final InvoiceRepository invoiceRepository;

    public InvoiceService(InvoiceRepository invoiceRepository) {
        this.invoiceRepository = invoiceRepository;
    }

    @Transactional
    public BillingDtos.CancelInvoiceResponse cancelInvoice(long invoiceId, long customerId) {
        Invoice invoice = invoiceRepository.findById(invoiceId)
                .orElseThrow(() -> new InvoiceNotFoundException(invoiceId));

        // Disguise "belongs to someone else" as "not found" so the API never confirms
        // the existence of another customer's invoice.
        if (invoice.customerId() != customerId) {
            throw new InvoiceNotFoundException(invoiceId);
        }

        if (invoice.status() != InvoiceStatus.UNPAID) {
            throw new InvoiceNotCancellableException(invoiceId, invoice.status());
        }

        // invoice is a managed entity inside this transaction; markCancelled() mutates
        // its state and the change is flushed by JPA dirty checking on commit.
        invoice.markCancelled();

        return new BillingDtos.CancelInvoiceResponse(invoiceId, InvoiceStatus.CANCELLED);
    }
}
